<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import api,{unwrap}from'@/api';import type{Orchard,PageData}from'@/types';import{Edit,Clock}from'@element-plus/icons-vue';import{useAuthStore}from'@/stores/auth';import{ElMessage}from'element-plus'
const auth=useAuthStore(),orchard=ref<Orchard|null>(null),history=ref<any[]>([]),dialog=ref(false),phenologyDialog=ref(false),form=reactive<any>({}),phenology=reactive({stage:'FRUIT_EXPANSION',effectiveDate:new Date().toISOString().slice(0,10),note:''})
const names:Record<string,string>={DORMANCY:'休眠/恢复期',SHOOT_GROWTH:'春梢生长期',FLOWERING:'开花期',FRUIT_SET:'坐果期',FRUIT_EXPANSION:'幼果膨大期',MATURITY:'成熟期',HARVEST:'采收期',POST_HARVEST:'采后管理期'}
async function load(){const d=unwrap<PageData<Orchard>>(await api.get('/orchards'));orchard.value=d.items[0];if(orchard.value){Object.assign(form,orchard.value);history.value=unwrap<PageData<any>>(await api.get(`/orchards/${orchard.value.id}/phenologies`)).items}}
async function save(){if(!orchard.value)return;await api.put(`/orchards/${orchard.value.id}`,form);ElMessage.success('果园档案已保存');dialog.value=false;load()}
async function savePhenology(){if(!orchard.value)return;await api.post(`/orchards/${orchard.value.id}/phenologies`,phenology);ElMessage.success('物候期已更新并保留历史');phenologyDialog.value=false;load()}onMounted(load)
</script><template><div v-if="orchard"><div class="page-title-row"><div><h2>{{orchard.name}}</h2><p>{{orchard.region}} · {{orchard.address}}</p></div><div v-if="auth.isAdmin" class="toolbar"><el-button :icon="Clock" @click="phenologyDialog=true">更新物候期</el-button><el-button type="primary" :icon="Edit" @click="dialog=true">编辑档案</el-button></div></div><div class="orchard-band"><div><span>面积</span><strong>{{orchard.areaMu}} 亩</strong></div><div><span>株数</span><strong>{{orchard.treeCount}} 株</strong></div><div><span>树龄</span><strong>{{orchard.treeAge}} 年</strong></div><div><span>灌溉</span><strong>{{orchard.irrigationMode}}</strong></div><div><span>物候期</span><strong>{{names[orchard.currentPhenology]}}</strong></div></div><div class="content-grid"><section class="panel"><header class="panel-header"><h3>基本档案</h3><span class="status-pill">{{orchard.status}}</span></header><dl class="detail-list"><div><dt>品种</dt><dd>{{orchard.variety}}</dd></div><div><dt>负责人</dt><dd>{{orchard.manager}}</dd></div><div><dt>所在地区</dt><dd>{{orchard.region}}</dd></div><div><dt>种植方式</dt><dd>露地栽培</dd></div><div><dt>灌溉方式</dt><dd>{{orchard.irrigationMode}}</dd></div></dl></section><section class="panel"><header class="panel-header"><h3>物候期历史</h3></header><el-timeline class="timeline"><el-timeline-item v-for="h in history" :key="h.id" :timestamp="h.effectiveDate" placement="top" color="#2e6b4e"><strong>{{names[h.stage]}}</strong><p>{{h.note}}</p></el-timeline-item></el-timeline></section></div><el-dialog v-model="dialog" title="编辑果园档案" width="min(680px,94vw)"><el-form label-position="top"><div class="edit-grid"><el-form-item label="果园名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="所在地区"><el-input v-model="form.region"/></el-form-item><el-form-item label="面积（亩）"><el-input-number v-model="form.areaMu" :min=".01"/></el-form-item><el-form-item label="株数"><el-input-number v-model="form.treeCount" :min="1"/></el-form-item><el-form-item label="树龄"><el-input-number v-model="form.treeAge" :min="0"/></el-form-item><el-form-item label="品种"><el-input v-model="form.variety"/></el-form-item><el-form-item label="灌溉方式"><el-input v-model="form.irrigationMode"/></el-form-item><el-form-item label="负责人"><el-input v-model="form.manager"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="phenologyDialog" title="更新物候期" width="min(460px,92vw)"><el-form label-position="top"><el-form-item label="物候期"><el-select v-model="phenology.stage" style="width:100%"><el-option v-for="(label,key) in names" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="phenology.effectiveDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="备注"><el-input v-model="phenology.note" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="phenologyDialog=false">取消</el-button><el-button type="primary" @click="savePhenology">确认更新</el-button></template></el-dialog></div></template><style scoped>.orchard-band{display:grid;grid-template-columns:repeat(5,1fr);background:#24352d;color:white;border-radius:6px;padding:20px 8px;margin-bottom:18px}.orchard-band>div{padding:4px 18px;border-right:1px solid #405249;display:flex;flex-direction:column;gap:7px}.orchard-band>div:last-child{border:0}.orchard-band span{font-size:10px;color:#a5b5ac}.orchard-band strong{font-size:17px}.detail-list{margin:0;padding:4px 18px}.detail-list div{display:grid;grid-template-columns:120px 1fr;padding:14px 0;border-bottom:1px solid var(--line)}dt{color:var(--muted);font-size:12px}dd{margin:0;font-size:13px}.timeline{padding:22px 24px}.timeline p{color:var(--muted);font-size:11px;margin:5px 0}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}@media(max-width:700px){.orchard-band{grid-template-columns:1fr 1fr}.orchard-band>div{border-bottom:1px solid #405249}.edit-grid{grid-template-columns:1fr}}</style>

